-- #############################################################################
-- 1. سد الثغرة SEC-FIX-01: تحصين التسجيل الذاتي ومنع تصعيد الرتب في handle_new_user
-- #############################################################################

CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS TRIGGER 
LANGUAGE plpgsql 
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  default_org_id UUID;
  user_role TEXT;
  user_scope TEXT;
  user_dashboard BOOLEAN;
  user_mobile BOOLEAN;
  raw_role TEXT;
BEGIN
  -- 🛡️ منع تصعيد الصلاحيات: أي تسجيل جديد عبر المتصفح/الواجهة لا يمكنه منح نفسه رتب إدارية
  raw_role := LOWER(COALESCE(
    NEW.raw_user_meta_data->>'role', 
    NEW.raw_user_meta_data->>'app_role', 
    'viewer'
  ));

  -- إذا حاول المستخدم طلب أي رتبة إدارية، يتم خفضها فوراً إلى viewer لحين اعتماد الأدمن
  IF raw_role IN ('super_admin', 'admin', 'owner', 'manager') THEN
    user_role := 'viewer';
  ELSE
    user_role := raw_role;
  END IF;

  -- تحديد نطاق الإشراف الافتراضي
  user_scope := COALESCE(
    NEW.raw_user_meta_data->>'hr_scope',
    'branch'
  );

  -- صلاحية لوحة القيادة الافتراضية
  user_dashboard := COALESCE(
    (NEW.raw_user_meta_data->>'can_view_dashboard')::BOOLEAN,
    false
  );

  -- صلاحية تطبيق الموبايل الافتراضية
  user_mobile := COALESCE(
    (NEW.raw_user_meta_data->>'can_access_mobile')::BOOLEAN,
    false
  );

  -- تحديد المنظمة: التحقق من وجود المنظمة فعلياً لمنع التلاعب
  IF NEW.raw_user_meta_data->>'org_id' IS NOT NULL AND NEW.raw_user_meta_data->>'org_id' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    SELECT id INTO default_org_id 
    FROM public.organizations 
    WHERE id = (NEW.raw_user_meta_data->>'org_id')::UUID;
  END IF;

  -- عدم إسناد المنشأة الرئيسية إلا في حالة المنشأة الوحيدة (البيئة التجريبية المغلقة)
  IF default_org_id IS NULL THEN
    IF (SELECT COUNT(*) FROM public.organizations) = 1 THEN
      SELECT id INTO default_org_id FROM public.organizations LIMIT 1;
    END IF;
  END IF;

  INSERT INTO public.profiles (
    id, 
    full_name, 
    role, 
    organization_id, 
    hr_scope, 
    can_view_dashboard, 
    can_access_mobile, 
    is_active
  )
  VALUES (
    NEW.id,
    COALESCE(NEW.raw_user_meta_data->>'full_name', NEW.email),
    user_role,
    default_org_id,
    user_scope,
    user_dashboard,
    user_mobile,
    true
  )
  ON CONFLICT (id) DO UPDATE SET
    full_name = EXCLUDED.full_name;
    -- 🛡️ حماية: عدم السماح بتعديل role أو organization_id عبر تحديث المستخدم لنفسه

  RETURN NEW;
END;
$$;


-- #############################################################################
-- 2. سد الثغرة SEC-FIX-02: توسيع الحارس الأمني لجدول profiles ليشمل INSERT و UPDATE
-- #############################################################################

CREATE OR REPLACE FUNCTION public.fn_guard_profile_role_tampering()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_caller_role TEXT;
    v_caller_id UUID := auth.uid();
BEGIN
    -- إذا كان الاستدعاء من خدمة داخلية للخادم بدون جلسة مستخدم (service_role أو triggers خادم auth)، نسمح به
    IF v_caller_id IS NULL THEN
        RETURN NEW;
    END IF;

    -- جلب رتبة المستخدم المستدعي للعملية
    SELECT role INTO v_caller_role FROM public.profiles WHERE id = v_caller_id;

    -- حالة الإدخال INSERT: منع أي مستخدم غير super_admin من إنشاء بروفايل برتبة إدارية
    IF TG_OP = 'INSERT' THEN
        IF COALESCE(NEW.role, '') IN ('super_admin', 'admin', 'owner', 'manager') THEN
            IF COALESCE(v_caller_role, '') NOT IN ('super_admin') THEN
                RAISE EXCEPTION 'TRIPRO_SECURITY_ALERT: غير مصرح لك بإنشاء حسابات ذات رتب أو صلاحيات إدارية عليا.';
            END IF;
        END IF;
    END IF;

    -- حالة التعديل UPDATE: منع تغيير الرتبة أو المنظمة أو الصلاحيات من قِبل غير super_admin
    IF TG_OP = 'UPDATE' THEN
        IF (NEW.role IS DISTINCT FROM OLD.role 
            OR NEW.organization_id IS DISTINCT FROM OLD.organization_id 
            OR NEW.role_id IS DISTINCT FROM OLD.role_id
            OR NEW.is_active IS DISTINCT FROM OLD.is_active) THEN
            
            IF COALESCE(v_caller_role, '') NOT IN ('super_admin') THEN
                RAISE EXCEPTION 'TRIPRO_SECURITY_ALERT: غير مصرح لك بتعديل الرتبة أو المنظمة أو الصلاحيات الإدارية عبر كونسول المتصفح.';
            END IF;
        END IF;
    END IF;

    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_guard_profile_role_tampering ON public.profiles;
CREATE TRIGGER trg_guard_profile_role_tampering
BEFORE INSERT OR UPDATE ON public.profiles
FOR EACH ROW
EXECUTE FUNCTION public.fn_guard_profile_role_tampering();


-- #############################################################################
-- 3. سد الثغرة SEC-FIX-03: تحصين دوال التوكن get_my_role و get_my_org ضد تزييف JWT
-- #############################################################################

CREATE OR REPLACE FUNCTION public.get_my_role() 
RETURNS text 
LANGUAGE plpgsql 
SECURITY DEFINER 
SET search_path = public
AS $$
DECLARE 
    _role text;
    _user_id uuid := auth.uid();
BEGIN
    IF _user_id IS NULL THEN
        RETURN 'anon';
    END IF;

    -- 🛡️ التحقق الحصري من جدول profiles المحمي بحارس قاعدة البيانات
    SELECT role INTO _role FROM public.profiles WHERE id = _user_id LIMIT 1;
    
    -- إذا لم يوجد بروفايل بعد، فحص app_metadata فقط (المحمية من السيرفر) وتجاهل user_metadata تماماً
    IF _role IS NULL THEN
        _role := NULLIF(current_setting('request.jwt.claims', true)::jsonb -> 'app_metadata' ->> 'role', '');
    END IF;

    RETURN COALESCE(_role, 'viewer');
END; 
$$;

CREATE OR REPLACE FUNCTION public.get_my_org() 
RETURNS uuid 
LANGUAGE plpgsql 
SECURITY DEFINER 
SET search_path = public
AS $$
DECLARE 
    _org_id uuid;
    _user_id uuid := auth.uid();
BEGIN
    IF _user_id IS NULL THEN
        RETURN NULL;
    END IF;

    -- فحص الجلسة المؤقتة إن وُجدت
    BEGIN
        _org_id := NULLIF(current_setting('app.current_org_id', true), '')::uuid;
        IF _org_id IS NOT NULL THEN RETURN _org_id; END IF;
    EXCEPTION WHEN OTHERS THEN NULL;
    END;

    -- 🛡️ التحقق الحصري من جدول profiles المحمي وتجاهل user_metadata الخاضع للعميل
    SELECT organization_id INTO _org_id FROM public.profiles WHERE id = _user_id LIMIT 1;
    
    IF _org_id IS NULL THEN
        _org_id := NULLIF(current_setting('request.jwt.claims', true)::jsonb -> 'app_metadata' ->> 'org_id', '')::uuid;
    END IF;

    RETURN _org_id;
END; 
$$;


-- #############################################################################
-- 4. سد الثغرة SEC-FIX-04: تحصين قائمة الدخل وفرض validate_tenant_access
-- #############################################################################

CREATE OR REPLACE FUNCTION public.get_income_statement_summary_rpc(
    p_org_id uuid DEFAULT NULL,
    p_start_date date DEFAULT CURRENT_DATE,
    p_end_date date DEFAULT CURRENT_DATE
)
RETURNS TABLE (
    account_id uuid,
    account_code text,
    account_name text,
    account_type text,
    is_group boolean,
    parent_id uuid,
    period_debit numeric,
    period_credit numeric,
    net_movement numeric
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_org_id uuid;
BEGIN
    -- 🛡️ فرض العزل التام للمنظمات
    v_org_id := public.validate_tenant_access(p_org_id);

    RETURN QUERY
    WITH tx AS (
        SELECT 
            jl.account_id,
            jl.debit,
            jl.credit
        FROM public.journal_lines jl
        JOIN public.journal_entries je ON jl.journal_entry_id = je.id
        WHERE je.status = 'posted'
          AND je.organization_id = v_org_id
          AND je.transaction_date >= p_start_date
          AND je.transaction_date <= p_end_date
          AND (je.reference IS NULL OR je.reference NOT LIKE 'CLOSE-%')
    )
    SELECT
        a.id AS account_id,
        a.code::text AS account_code,
        a.name::text AS account_name,
        a.type::text AS account_type,
        COALESCE(a.is_group, false) AS is_group,
        a.parent_id AS parent_id,
        COALESCE(SUM(tx.debit), 0)::numeric(19,4) AS period_debit,
        COALESCE(SUM(tx.credit), 0)::numeric(19,4) AS period_credit,
        COALESCE(SUM(tx.debit - tx.credit), 0)::numeric(19,4) AS net_movement
    FROM
        public.accounts a
    JOIN tx ON a.id = tx.account_id
    WHERE
        a.organization_id = v_org_id
    GROUP BY
        a.id, a.code, a.name, a.type, a.is_group, a.parent_id
    ORDER BY
        a.code;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.get_income_statement_summary_rpc(uuid, date, date) FROM anon, public;
GRANT EXECUTE ON FUNCTION public.get_income_statement_summary_rpc(uuid, date, date) TO authenticated, service_role;


-- #############################################################################
-- 5. سد الثغرة SEC-FIX-05: تحصين ميزان المراجعة المجمع والرصيد الافتتاحي
-- #############################################################################

CREATE OR REPLACE FUNCTION public.get_trial_balance_summary_rpc(
    p_org_id uuid DEFAULT NULL,
    p_start_date date DEFAULT '1970-01-01',
    p_end_date date DEFAULT CURRENT_DATE
)
RETURNS TABLE (
    account_id uuid,
    account_code text,
    account_name text,
    account_type text,
    is_group boolean,
    parent_id uuid,
    opening_balance numeric,
    period_debit numeric,
    period_credit numeric,
    closing_balance numeric
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_org_id uuid;
BEGIN
    -- 🛡️ فرض العزل التام للمنظمات
    v_org_id := public.validate_tenant_access(p_org_id);

    RETURN QUERY
    WITH tx AS (
        SELECT 
            jl.account_id,
            jl.debit,
            jl.credit,
            je.transaction_date
        FROM public.journal_lines jl
        JOIN public.journal_entries je ON jl.journal_entry_id = je.id
        WHERE je.status = 'posted'
          AND je.organization_id = v_org_id
          AND je.transaction_date <= p_end_date
    ),
    acc_summary AS (
        SELECT
            COALESCE(a.id, tx.account_id) AS acc_id,
            COALESCE(a.code, 'UNKNOWN') AS acc_code,
            COALESCE(a.name, 'حساب محذوف / غير معرف') AS acc_name,
            COALESCE(a.type, 'other') AS acc_type,
            COALESCE(a.is_group, false) AS acc_is_group,
            a.parent_id AS acc_parent_id,
            COALESCE(SUM(CASE WHEN tx.transaction_date < p_start_date THEN tx.debit - tx.credit ELSE 0 END), 0)::numeric(19,4) AS open_bal,
            COALESCE(SUM(CASE WHEN tx.transaction_date >= p_start_date AND tx.transaction_date <= p_end_date THEN tx.debit ELSE 0 END), 0)::numeric(19,4) AS per_debit,
            COALESCE(SUM(CASE WHEN tx.transaction_date >= p_start_date AND tx.transaction_date <= p_end_date THEN tx.credit ELSE 0 END), 0)::numeric(19,4) AS per_credit,
            COALESCE(SUM(tx.debit - tx.credit), 0)::numeric(19,4) AS close_bal
        FROM
            public.accounts a
        FULL OUTER JOIN tx ON a.id = tx.account_id
        WHERE
            a.organization_id = v_org_id OR (a.organization_id IS NULL AND tx.account_id IS NOT NULL)
        GROUP BY
            COALESCE(a.id, tx.account_id),
            a.code,
            a.name,
            a.type,
            a.is_group,
            a.parent_id
    )
    SELECT
        acc_id AS account_id,
        acc_code AS account_code,
        acc_name AS account_name,
        acc_type AS account_type,
        acc_is_group AS is_group,
        acc_parent_id AS parent_id,
        open_bal AS opening_balance,
        per_debit AS period_debit,
        per_credit AS period_credit,
        close_bal AS closing_balance
    FROM acc_summary
    ORDER BY acc_code;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.get_trial_balance_summary_rpc(uuid, date, date) FROM anon, public;
GRANT EXECUTE ON FUNCTION public.get_trial_balance_summary_rpc(uuid, date, date) TO authenticated, service_role;


CREATE OR REPLACE FUNCTION public.get_account_opening_balance_rpc(
    p_account_ids uuid[],
    p_start_date date,
    p_org_id uuid DEFAULT NULL
)
RETURNS numeric
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_org_id uuid;
    v_opening_balance numeric;
BEGIN
    v_org_id := public.validate_tenant_access(p_org_id);

    SELECT COALESCE(SUM(jl.debit - jl.credit), 0)::numeric(19,4)
    INTO v_opening_balance
    FROM public.journal_lines jl
    JOIN public.journal_entries je ON jl.journal_entry_id = je.id
    WHERE jl.account_id = ANY(p_account_ids)
      AND je.status = 'posted'
      AND je.organization_id = v_org_id
      AND je.transaction_date < p_start_date;

    RETURN COALESCE(v_opening_balance, 0);
END;
$$;

REVOKE EXECUTE ON FUNCTION public.get_account_opening_balance_rpc(uuid[], date, uuid) FROM anon, public;
GRANT EXECUTE ON FUNCTION public.get_account_opening_balance_rpc(uuid[], date, uuid) TO authenticated, service_role;


-- تحصين ميزان المراجعة المحدث get_trial_balance_mv إن وُجد
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'get_trial_balance_mv' AND pronamespace = 'public'::regnamespace) THEN
        EXECUTE $TB_MV$
        CREATE OR REPLACE FUNCTION public.get_trial_balance_mv(
            p_org_id uuid DEFAULT NULL
        )
        RETURNS TABLE(
            account_id   uuid,
            account_code text,
            account_name text,
            account_type text,
            parent_id    uuid,
            total_debit  numeric,
            total_credit numeric,
            net_balance  numeric
        )
        LANGUAGE plpgsql
        SECURITY DEFINER
        SET search_path = public
        AS $FN$
        DECLARE
            v_org_id uuid;
        BEGIN
            v_org_id := public.validate_tenant_access(p_org_id);

            RETURN QUERY
            SELECT
                mv.account_id,
                mv.account_code,
                mv.account_name,
                mv.account_type,
                mv.parent_id,
                mv.total_debit,
                mv.total_credit,
                mv.net_balance
            FROM public.mv_trial_balance mv
            WHERE mv.organization_id = v_org_id
            ORDER BY mv.account_code;
        END;
        $FN$;
        $TB_MV$;
        REVOKE EXECUTE ON FUNCTION public.get_trial_balance_mv(uuid) FROM anon, public;
        GRANT EXECUTE ON FUNCTION public.get_trial_balance_mv(uuid) TO authenticated, service_role;
    END IF;
END $$;


-- #############################################################################
-- 6. سد الثغرة SEC-FIX-06: تحصين ملخص التدقيق المالي وإعدادات الشركة والمخزون
-- #############################################################################

-- أ. تحصين get_financial_audit_summary
CREATE OR REPLACE FUNCTION public.get_financial_audit_summary(
    p_org_id text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_org_id uuid;
    v_caller_role text;
    v_caller_id uuid := auth.uid();
    v_total_debit numeric := 0;
    v_total_credit numeric := 0;
    v_gl_variance numeric := 0;
    v_unbalanced_count integer := 0;
    v_customers_balance numeric := 0;
    v_ar_gl_balance numeric := 0;
    v_ar_variance numeric := 0;
    v_suppliers_balance numeric := 0;
    v_ap_gl_balance numeric := 0;
    v_ap_variance numeric := 0;
    v_stock_valuation numeric := 0;
    v_inv_gl_balance numeric := 0;
    v_inv_variance numeric := 0;
    v_total_vouchers integer := 0;
    v_mismatched_vouchers integer := 0;
    v_overall_status text := 'passed';
    v_checks jsonb := '[]'::jsonb;
BEGIN
    IF v_caller_id IS NOT NULL THEN
        SELECT role INTO v_caller_role FROM public.profiles WHERE id = v_caller_id;
        IF COALESCE(v_caller_role, '') NOT IN ('super_admin', 'admin', 'manager', 'accountant') THEN
            RAISE EXCEPTION 'TRIPRO_SECURITY_ALERT: تقارير التدقيق المالي تقتصر على المدراء والمحاسبين المعتمدين.';
        END IF;
    END IF;

    IF p_org_id IS NOT NULL AND p_org_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        v_org_id := public.validate_tenant_access(p_org_id::uuid);
    ELSE
        v_org_id := public.validate_tenant_access(NULL);
    END IF;

    -- 1. الركن الأول: توازن دفتر الأستاذ العام
    SELECT 
        COALESCE(SUM(jl.debit), 0)::numeric,
        COALESCE(SUM(jl.credit), 0)::numeric
    INTO v_total_debit, v_total_credit
    FROM public.journal_lines jl
    JOIN public.journal_entries je ON jl.journal_entry_id = je.id
    WHERE je.organization_id = v_org_id
      AND je.status = 'posted';

    v_gl_variance := ABS(v_total_debit - v_total_credit);

    SELECT COUNT(*) INTO v_unbalanced_count
    FROM (
        SELECT je.id
        FROM public.journal_entries je
        JOIN public.journal_lines jl ON je.id = jl.journal_entry_id
        WHERE je.organization_id = v_org_id
          AND je.status = 'posted'
        GROUP BY je.id
        HAVING ABS(SUM(jl.debit) - SUM(jl.credit)) > 0.01
    ) sub;

    IF v_gl_variance > 0.05 OR v_unbalanced_count > 0 THEN
        v_overall_status := 'failed';
        v_checks := v_checks || jsonb_build_object(
            'id', 'pillar-gl',
            'pillar', 'gl_balance',
            'title', 'توازن الأستاذ العام (إجمالي المدين = إجمالي الدائن)',
            'expected', ROUND(v_total_debit, 2),
            'actual', ROUND(v_total_credit, 2),
            'variance', ROUND(v_gl_variance, 2),
            'status', 'failed',
            'notes', format('يوجد عدم توازن في الأستاذ العام بقيمة %s ج.م (عدد %s قيد غير متوازن)', ROUND(v_gl_variance, 2), v_unbalanced_count)
        );
    ELSE
        v_checks := v_checks || jsonb_build_object(
            'id', 'pillar-gl',
            'pillar', 'gl_balance',
            'title', 'توازن الأستاذ العام (إجمالي المدين = إجمالي الدائن)',
            'expected', ROUND(v_total_debit, 2),
            'actual', ROUND(v_total_credit, 2),
            'variance', 0.00,
            'status', 'passed',
            'notes', format('الأستاذ العام متوازن تماماً: مدين (%s ج.م) = دائن (%s ج.م)', to_char(v_total_debit, 'FM999,999,999,990.00'), to_char(v_total_credit, 'FM999,999,999,990.00'))
        );
    END IF;

    -- النتيجة النهائية المجمعة
    RETURN jsonb_build_object(
        'success', true,
        'organization_id', v_org_id,
        'timestamp', now(),
        'overall_status', v_overall_status,
        'checks', v_checks
    );
END;
$$;

REVOKE EXECUTE ON FUNCTION public.get_financial_audit_summary(text) FROM anon, public;
GRANT EXECUTE ON FUNCTION public.get_financial_audit_summary(text) TO authenticated, service_role;


-- ب. تحصين إعدادات الشركة get_safe_company_settings
CREATE OR REPLACE FUNCTION public.get_safe_company_settings(p_org_id UUID DEFAULT NULL)
RETURNS TABLE (
    id UUID,
    organization_id UUID,
    company_name TEXT,
    phone TEXT,
    address TEXT,
    tax_number TEXT,
    commercial_register TEXT,
    currency TEXT,
    tax_rate NUMERIC,
    s3_endpoint TEXT,
    s3_bucket TEXT,
    s3_region TEXT,
    s3_is_active BOOLEAN,
    s3_access_key_masked TEXT,
    has_s3_secret BOOLEAN
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_org_id UUID;
BEGIN
    v_org_id := public.validate_tenant_access(p_org_id);
    
    RETURN QUERY
    SELECT 
        cs.id,
        cs.organization_id,
        cs.company_name,
        cs.phone,
        cs.address,
        cs.tax_number,
        cs.commercial_register,
        cs.currency,
        cs.tax_rate,
        cs.s3_endpoint,
        cs.s3_bucket,
        cs.s3_region,
        cs.s3_is_active,
        CASE 
            WHEN cs.s3_access_key IS NOT NULL AND length(cs.s3_access_key) > 8 
            THEN substr(cs.s3_access_key, 1, 4) || '••••••••' || substr(cs.s3_access_key, length(cs.s3_access_key)-3)
            ELSE '••••••••'
        END AS s3_access_key_masked,
        (cs.s3_secret_key IS NOT NULL AND length(cs.s3_secret_key) > 0) AS has_s3_secret
    FROM company_settings cs
    WHERE cs.organization_id = v_org_id
    LIMIT 1;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.get_safe_company_settings(UUID) FROM anon, public;
GRANT EXECUTE ON FUNCTION public.get_safe_company_settings(UUID) TO authenticated, service_role;


-- ج. تحصين استعلام حركات المخزون get_product_stock_movements_rpc
CREATE OR REPLACE FUNCTION public.get_product_stock_movements_rpc(
    p_product_id    UUID,
    p_org_id        UUID,
    p_warehouse_id  UUID DEFAULT NULL,
    p_start_date    DATE DEFAULT NULL,
    p_end_date      DATE DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_org_id          UUID;
    v_opening_balance NUMERIC(15, 4) := 0;
    v_total_in        NUMERIC(15, 4) := 0;
    v_total_out       NUMERIC(15, 4) := 0;
    v_net_movement    NUMERIC(15, 4) := 0;
    v_closing_balance NUMERIC(15, 4) := 0;
    v_movements       JSONB := '[]'::JSONB;
BEGIN
    v_org_id := public.validate_tenant_access(p_org_id);

    WITH all_movements AS (
        SELECT 
            ii.id::text AS id,
            i.invoice_date::text AS date,
            'OUT' AS type,
            ii.quantity::numeric AS quantity,
            ii.uom_id::text AS uom_id,
            'فاتورة مبيعات' AS document_type,
            COALESCE(i.invoice_number, '-') AS document_number,
            i.warehouse_id::text AS warehouse_id,
            w.name AS warehouse_name,
            i.created_at::text AS created_at,
            i.notes,
            ii.unit_price::numeric AS unit_price,
            NULL::numeric AS unit_cost
        FROM invoice_items ii
        JOIN invoices i ON ii.invoice_id = i.id
        LEFT JOIN warehouses w ON i.warehouse_id = w.id
        WHERE ii.product_id = p_product_id
          AND i.organization_id = v_org_id
          AND i.status NOT IN ('draft', 'cancelled')
          AND (p_warehouse_id IS NULL OR i.warehouse_id = p_warehouse_id)
          AND (p_start_date IS NULL OR i.invoice_date >= p_start_date)
          AND (p_end_date IS NULL OR i.invoice_date <= p_end_date)

        UNION ALL

        SELECT 
            pii.id::text AS id,
            pi.invoice_date::text AS date,
            'IN' AS type,
            pii.quantity::numeric AS quantity,
            pii.uom_id::text AS uom_id,
            'فاتورة مشتريات' AS document_type,
            COALESCE(pi.invoice_number, '-') AS document_number,
            pi.warehouse_id::text AS warehouse_id,
            w.name AS warehouse_name,
            pi.created_at::text AS created_at,
            pi.notes,
            NULL::numeric AS unit_price,
            pii.unit_price::numeric AS unit_cost
        FROM purchase_invoice_items pii
        JOIN purchase_invoices pi ON pii.purchase_invoice_id = pi.id
        LEFT JOIN warehouses w ON pi.warehouse_id = w.id
        WHERE pii.product_id = p_product_id
          AND pi.organization_id = v_org_id
          AND pi.status NOT IN ('draft', 'cancelled')
          AND (p_warehouse_id IS NULL OR pi.warehouse_id = p_warehouse_id)
          AND (p_start_date IS NULL OR pi.invoice_date >= p_start_date)
          AND (p_end_date IS NULL OR pi.invoice_date <= p_end_date)
    )
    SELECT 
        COALESCE(SUM(CASE WHEN type = 'IN' THEN quantity ELSE 0 END), 0),
        COALESCE(SUM(CASE WHEN type = 'OUT' THEN quantity ELSE 0 END), 0),
        COALESCE(jsonb_agg(row_to_json(m.*) ORDER BY m.date DESC, m.created_at DESC), '[]'::JSONB)
    INTO v_total_in, v_total_out, v_movements
    FROM all_movements m;

    v_net_movement := v_total_in - v_total_out;
    v_closing_balance := v_opening_balance + v_net_movement;

    RETURN jsonb_build_object(
        'product_id', p_product_id,
        'organization_id', v_org_id,
        'opening_balance', v_opening_balance,
        'total_in', v_total_in,
        'total_out', v_total_out,
        'net_movement', v_net_movement,
        'closing_balance', v_closing_balance,
        'movements_count', jsonb_array_length(v_movements),
        'movements', v_movements
    );
END;
$$;

REVOKE EXECUTE ON FUNCTION public.get_product_stock_movements_rpc(UUID, UUID, UUID, DATE, DATE) FROM anon, public;
GRANT EXECUTE ON FUNCTION public.get_product_stock_movements_rpc(UUID, UUID, UUID, DATE, DATE) TO authenticated, service_role;


-- #############################################################################
-- 7. سد الثغرة SEC-FIX-07: تحصين دوال مسيرات الرواتب وإعادة احتساب الأرصدة
-- #############################################################################

-- أ. تحصين cancel_payroll_accrual_rpc
CREATE OR REPLACE FUNCTION public.cancel_payroll_accrual_rpc(
    p_payroll_id uuid,
    p_org_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_payroll record;
    v_org_id uuid;
    v_caller_role text;
    v_caller_id uuid := auth.uid();
BEGIN
    IF v_caller_id IS NOT NULL THEN
        SELECT role INTO v_caller_role FROM public.profiles WHERE id = v_caller_id;
        IF COALESCE(v_caller_role, '') NOT IN ('super_admin', 'admin', 'manager', 'accountant', 'hr') THEN
            RAISE EXCEPTION 'TRIPRO_SECURITY_ALERT: لا تملك الصلاحية اللازمة لإلغاء قيود مسيرات الرواتب.';
        END IF;
    END IF;

    SELECT * INTO v_payroll FROM public.payrolls WHERE id = p_payroll_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'مسير الرواتب المحدد غير موجود.';
    END IF;

    v_org_id := public.validate_tenant_access(COALESCE(p_org_id, v_payroll.organization_id));

    IF v_payroll.organization_id <> v_org_id THEN
        RAISE EXCEPTION 'TRIPRO_SECURITY_ALERT: هذا المسير يتبع منشأة أخرى ولا تملك صلاحية إلغائه.';
    END IF;

    IF v_payroll.status = 'paid' THEN
        RAISE EXCEPTION 'لا يمكن إلغاء مسير رواتب تم صرفه بالفعل وتسويته في البنك/الخزينة.';
    END IF;

    UPDATE public.employee_advances 
    SET status = 'paid', payroll_item_id = NULL 
    WHERE payroll_item_id IN (SELECT id FROM public.payroll_items WHERE payroll_id = p_payroll_id);

    UPDATE public.payroll_variables 
    SET is_processed = false 
    WHERE month = v_payroll.payroll_month AND year = v_payroll.payroll_year AND organization_id = v_org_id;

    DELETE FROM public.journal_entries 
    WHERE (id = v_payroll.accrual_je_id OR (related_document_id = p_payroll_id AND related_document_type = 'payroll'))
    AND organization_id = v_org_id;

    DELETE FROM public.payrolls WHERE id = p_payroll_id;

    RETURN jsonb_build_object('success', true, 'message', 'تم إلغاء قيد استحقاق المسير بنجاح وإعادة جميع السلف كـ قائمة.');
END;
$$;

REVOKE EXECUTE ON FUNCTION public.cancel_payroll_accrual_rpc(uuid, uuid) FROM anon, public;
GRANT EXECUTE ON FUNCTION public.cancel_payroll_accrual_rpc(uuid, uuid) TO authenticated, service_role;


-- ب. تحصين recalculate_all_system_balances
CREATE OR REPLACE FUNCTION public.recalculate_all_system_balances(
    p_org_id uuid DEFAULT NULL
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_org_id uuid;
    v_caller_role text;
    v_caller_id uuid := auth.uid();
BEGIN
    IF v_caller_id IS NOT NULL THEN
        SELECT role INTO v_caller_role FROM public.profiles WHERE id = v_caller_id;
        IF COALESCE(v_caller_role, '') NOT IN ('super_admin', 'admin', 'manager', 'accountant') THEN
            RAISE EXCEPTION 'TRIPRO_SECURITY_ALERT: إعادة احتساب أرصدة النظام تقتصر على المدراء والمحاسبين المعتمدين.';
        END IF;
    END IF;

    v_org_id := public.validate_tenant_access(p_org_id);

    -- 1. تشغيل المحاذاة والإصلاح الذاتي لسندات الصرف والقبض
    BEGIN
        PERFORM public.auto_reconcile_all_vouchers_with_gl(v_org_id);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;

    -- 2. تحديث أرصدة شجرة الحسابات العامة (Accounts)
    UPDATE public.accounts a
    SET balance = COALESCE(b.calculated_balance, 0)
    FROM (
        SELECT 
            jl.account_id,
            SUM(
                CASE 
                    WHEN acc.type IN ('asset', 'expense') OR acc.code LIKE '1%' OR acc.code LIKE '5%' 
                        THEN (COALESCE(jl.debit, 0) - COALESCE(jl.credit, 0))
                    ELSE 
                        (COALESCE(jl.credit, 0) - COALESCE(jl.debit, 0))
                END
            ) AS calculated_balance
        FROM public.journal_lines jl
        JOIN public.journal_entries je ON jl.journal_entry_id = je.id
        JOIN public.accounts acc ON jl.account_id = acc.id
        WHERE je.status = 'posted'
          AND je.organization_id = v_org_id
        GROUP BY jl.account_id
    ) b
    WHERE a.id = b.account_id
      AND a.organization_id = v_org_id;

    -- 3. تصفير الحسابات التي ليس عليها أي حركات مرحلة لنفس المنشأة
    UPDATE public.accounts
    SET balance = 0
    WHERE id NOT IN (
        SELECT DISTINCT jl.account_id 
        FROM public.journal_lines jl
        JOIN public.journal_entries je ON jl.journal_entry_id = je.id
        WHERE je.status = 'posted'
          AND je.organization_id = v_org_id
    )
    AND organization_id = v_org_id;

    -- 4. تحديث أرصدة العملاء (Customers)
    IF EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'recalculate_customer_balances' AND pronamespace = 'public'::regnamespace) THEN
        PERFORM public.recalculate_customer_balances(v_org_id);
    END IF;

    -- 5. تحديث أرصدة الموردين (Suppliers)
    IF EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'recalculate_supplier_balances' AND pronamespace = 'public'::regnamespace) THEN
        PERFORM public.recalculate_supplier_balances(v_org_id);
    END IF;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.recalculate_all_system_balances(uuid) FROM anon, public;
GRANT EXECUTE ON FUNCTION public.recalculate_all_system_balances(uuid) TO authenticated, service_role;


-- #############################################################################
-- 8. سد الثغرة SEC-FIX-08: منع مدراء المنشآت من تعديل صلاحيات مستخدمي منشآت أخرى
-- #############################################################################

CREATE OR REPLACE FUNCTION public.sync_user_permissions(
  p_user_id        uuid,
  p_permission_ids uuid[]
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_caller_role TEXT;
  v_caller_org UUID;
  v_target_org UUID;
  v_caller_id UUID := auth.uid();
BEGIN
  IF v_caller_id IS NOT NULL THEN
    SELECT role, organization_id INTO v_caller_role, v_caller_org 
    FROM public.profiles 
    WHERE id = v_caller_id;

    IF COALESCE(v_caller_role, '') NOT IN ('super_admin', 'admin') THEN
      RAISE EXCEPTION 'TRIPRO_SECURITY_ALERT: إدارة الصلاحيات المباشرة تقتصر على مدراء النظام المعتمدين فقط.';
    END IF;

    -- 🛡️ منع الآدمن العادي من تعديل صلاحيات مستخدم في شركة أخرى
    IF v_caller_role <> 'super_admin' THEN
      SELECT organization_id INTO v_target_org FROM public.profiles WHERE id = p_user_id;
      IF v_target_org IS DISTINCT FROM v_caller_org THEN
        RAISE EXCEPTION 'TRIPRO_SECURITY_ALERT: غير مصرح لك بإدارة صلاحيات مستخدم يتبع منشأة أخرى.';
      END IF;
    END IF;
  END IF;

  DELETE FROM public.user_permissions WHERE user_id = p_user_id;

  IF array_length(p_permission_ids, 1) > 0 THEN
    INSERT INTO public.user_permissions (user_id, permission_id, granted)
    SELECT p_user_id, unnest(p_permission_ids), true
    ON CONFLICT (user_id, permission_id) DO UPDATE SET granted = true;
  END IF;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.sync_user_permissions(uuid, uuid[]) FROM anon, public;
GRANT EXECUTE ON FUNCTION public.sync_user_permissions(uuid, uuid[]) TO authenticated, service_role;

